def test_sentiment_for_text_deterministic() -> None:
    assert sentiment_for_text("I love this amazing episode") == ("positive", 2)
    assert sentiment_for_text("This was boring and awful") == ("negative", -2)
    assert sentiment_for_text("Just a comment without sentiment words") == ("neutral", 0)
    assert sentiment_for_text("") == ("neutral", 0)


def test_get_social_account_profile_posts_filters_all_captions(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(social_repo, "_assert_social_account_profile_exists", lambda *_args, **_kwargs: [])
    monkeypatch.setattr(
        social_repo,
        "_instagram_social_account_profile_dataset_rows",
        lambda account_handle, *, search=None: (
            [
                {
                    "id": "post-1",
                    "source_id": "source-1",
                    "posted_at": "2026-03-22T12:00:00Z",
                    "caption": "BravoCon backstage with @andycohen",
                    "show_name": "Watch What Happens Live",
                    "season_number": 21,
                    "hashtags": ["BravoCon"],
                    "mentions": ["andycohen"],
                    "source_account": "bravotv",
                    "_profile_match_mode": "owner",
                    "_profile_source_surface": "materialized",
                }
            ]
            if account_handle == "bravotv" and search == "#BravoCon"
            else []
        ),
    )
    monkeypatch.setattr(
        social_repo,
        "_social_account_profile_analysis_rows",
        lambda *_args, **_kwargs: pytest.fail("instagram search should stay on the touching-posts dataset"),
    )

    payload = social_repo.get_social_account_profile_posts(
        "instagram",
        "bravotv",
        page=1,
        page_size=25,
        search="#BravoCon",
    )

    assert payload["pagination"]["total"] == 1
    assert [item["id"] for item in payload["items"]] == ["post-1"]


