def test_instagram_social_account_profile_dataset_rows_applies_limit_to_source_queries(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    captured: dict[str, int | None] = {}

    def _fake_fetch_materialized(
        _platform: str,
        _account_handle: str,
        *,
        limit=None,
        **_kwargs: Any,
    ) -> list[dict[str, Any]]:
        captured["materialized_limit"] = limit
        return [
            {
                "id": "materialized-1",
                "source_id": "same-post",
                "posted_at": "2026-03-22T12:00:00Z",
                "source_account": "bravotv",
            }
        ]

    def _fake_fetch_catalog(_account_handle: str, *, limit=None, posted_since=None) -> list[dict[str, Any]]:
        captured["catalog_limit"] = limit
        captured["catalog_posted_since"] = posted_since
        return [
            {
                "id": "catalog-1",
                "source_id": "same-post",
                "posted_at": "2026-03-22T12:00:00Z",
                "source_account": "bravotv",
            },
            {
                "id": "catalog-2",
                "source_id": "catalog-only",
                "posted_at": "2026-03-21T12:00:00Z",
                "source_account": "bravotv",
            },
        ]

    monkeypatch.setattr(
        social_repo,
        "_fetch_social_account_profile_rows",
        _fake_fetch_materialized,
    )
    monkeypatch.setattr(
        social_repo,
        "_fetch_instagram_touching_catalog_rows",
        _fake_fetch_catalog,
    )
    monkeypatch.setattr(
        social_repo,
        "_build_social_account_profile_known_handle_identity_index",
        lambda *_args, **_kwargs: {},
    )
    monkeypatch.setattr(
        social_repo,
        "_social_account_profile_row_matches_search",
        lambda *_args, **_kwargs: True,
    )

    rows = social_repo._instagram_social_account_profile_dataset_rows("bravotv", limit=25)

    assert captured["materialized_limit"] == 25
    assert captured["catalog_limit"] == 25
    assert captured["catalog_posted_since"] is None
    assert [row["id"] for row in rows] == ["materialized-1", "catalog-2"]


