def test_get_season_context_caches_stable_reads(monkeypatch: pytest.MonkeyPatch) -> None:
    calls: list[tuple[str, list[object] | None]] = []

    def _fake_fetch_one(sql: str, params: list[object] | None = None) -> dict[str, object] | None:
        calls.append((sql, params))
        normalized = " ".join(sql.split()).lower()
        if "from core.seasons s" in normalized:
            return {
                "season_id": "season-1",
                "show_id": "show-1",
                "season_number": 6,
                "air_date": date(2026, 1, 8),
                "show_name": "Test Show",
                "show_slug": "test-show",
            }
        if "from core.episodes e" in normalized:
            return {"air_date": date(2026, 1, 15)}
        raise AssertionError(f"Unexpected query: {sql}")

    monkeypatch.setattr(social_repo.pg, "fetch_one", _fake_fetch_one)

    first = social_repo.get_season_context("season-1")
    second = social_repo.get_season_context("season-1")

    assert first.season_id == "season-1"
    assert second.season_id == "season-1"
    assert len(calls) == 2


def test_build_platform_posts_shards_collapses_youtube_week_window_to_single_shard() -> None:
    start_dt = datetime(2025, 9, 17, 0, 0, tzinfo=UTC)
    end_dt = datetime(2025, 9, 23, 23, 59, 59, tzinfo=UTC)
    schedule = social_repo._build_ingest_shard_schedule(
        date_start=start_dt,
        date_end=end_dt,
        runner_strategy="adaptive_dual_runner",
        runner_count=2,
        window_shard_hours=4,
        runner_b_start_offset_hours=0,
        day_weight_profile="uniform",
        priority_mode="fifo",
    )

    shards = social_repo._build_platform_posts_shards(
        platform="youtube",
        schedule=schedule,
        date_start=start_dt,
        date_end=end_dt,
    )

    assert len(shards) == 1
    assert shards[0].window_start == start_dt
    assert shards[0].window_end == end_dt
    assert shards[0].runner_lane == "A"


