def test_week_summary_fast_threads_excludes_irrelevant_rows(monkeypatch: pytest.MonkeyPatch) -> None:
    context = SeasonContext(
        season_id="season-1",
        show_id="show-1",
        show_name="The Real Housewives of Salt Lake City",
        season_number=6,
        anchor_date=date(2025, 9, 16),
        show_slug="rhoslc",
    )
    monkeypatch.setattr(social_repo, "get_season_context", lambda _season_id: context)

    def fake_fetch_all(sql: str, params: list[Any]) -> list[dict[str, Any]]:
        normalized = " ".join(sql.lower().split())
        if "from social.meta_threads_posts p" in normalized:
            return [
                {
                    "id": "thread-rhoc",
                    "text": "Still thinking about this",
                    "raw_data": {"topic": "RHOC"},
                    "likes": 200,
                    "replies_count": 1,
                    "reposts": 2,
                    "quotes": 0,
                    "views": 9000,
                },
                {
                    "id": "thread-rhoslc",
                    "text": "Still thinking about this #RHOSLC",
                    "raw_data": {"topic": "RHOSLC"},
                    "likes": 217,
                    "replies_count": 6,
                    "reposts": 13,
                    "quotes": 0,
                    "views": 9177,
                },
            ]
        if "from social.meta_threads_comments c" in normalized:
            assert params == [["thread-rhoslc"]]
            return [{"post_id": "thread-rhoslc", "saved_comments": 6}]
        raise AssertionError(f"Unexpected SQL: {sql}")

    monkeypatch.setattr(social_repo.pg, "fetch_all", fake_fetch_all)

    payload = _week_summary_fast_threads(
        season_id=context.season_id,
        start_dt=datetime(2025, 9, 17, tzinfo=UTC),
        end_dt=datetime(2025, 9, 24, tzinfo=UTC),
        account_handles={"bravo"},
        source_scope="bravo",
    )

    assert payload["total_posts"] == 1
    assert payload["totals"]["posts"] == 1
    assert payload["totals"]["total_comments"] == 6
    assert payload["totals"]["saved_comments_total"] == 6
    assert payload["totals"]["total_engagement"] == 9413


def test_upsert_youtube_video_persists_short_flags(monkeypatch) -> None:
    captured: dict[str, object] = {}

    def _fake_upsert(table: str, payload: dict[str, object], *, conflict_col: str, conn=None):
        del conn
        captured["table"] = table
        captured["payload"] = payload
        captured["conflict_col"] = conflict_col
        return {"id": "db-yt-1"}

    monkeypatch.setattr(social_repo, "_pg_upsert", _fake_upsert)
    original_has_column = social_repo._platform_posts_has_column

    def _fake_has_column(platform: str, column: str) -> bool:
        if platform == "youtube" and column in {"is_short", "source_surface"}:
            return True
        return original_has_column(platform, column)

    monkeypatch.setattr(social_repo, "_platform_posts_has_column", _fake_has_column)
    context = SeasonContext(
        season_id="season-yt-upsert",
        show_id="show-yt-upsert",
        show_name="Test Show",
        season_number=6,
        anchor_date=date(2025, 8, 14),
    )
    video = SimpleNamespace(
        video_id="short-abc",
        channel_id="channel-1",
        channel_title="Bravo",
        title="You guys! Seriously! What about Britani! #RHOSLC #BritaniBateman #RealityTV",
        description="",
        duration="PT45S",
        duration_seconds=45,
        views=100,
        likes=10,
        comments=5,
        thumbnail_url="https://img.test/short.jpg",
        published_at=datetime(2025, 8, 14, tzinfo=UTC),
        is_short=True,
        source_surface="shorts",
        to_dict=lambda: {"video_id": "short-abc"},
    )

    payload = social_repo._upsert_youtube_video(
        context,
        job_id="job-yt-upsert",
        account="bravo",
        video=video,
        conn=None,
    )

    assert payload == {"id": "db-yt-1"}
    assert captured["table"] == "youtube_videos"
    assert captured["conflict_col"] == "video_id"
    saved = captured["payload"]
    assert isinstance(saved, dict)
    assert saved["is_short"] is True
    assert saved["source_surface"] == "shorts"
    assert saved["title"] == ""
    assert saved["description"] == "You guys! Seriously! What about Britani! #RHOSLC #BritaniBateman #RealityTV"
    assert saved["hashtags"] == ["RHOSLC", "BritaniBateman", "RealityTV"]


