    assert post["tagged_users_detail"][0]["url"] == "https://www.instagram.com/tagged_user/"
    assert post["tagged_users_detail"][0]["tag_x"] == 0.42
    assert post["tagged_users_detail"][0]["tag_y"] == 0.58
