    assert len(payload["queue"]["stuck_jobs"]) == 2
    assert payload["queue"]["stuck_jobs"][0]["stuck_reason"] == "running_stale_heartbeat"
    assert payload["queue"]["stuck_jobs"][1]["stuck_reason"] == "retrying_stale_timeout"


